import numpy as np
from PIL import Image
from scipy.ndimage import distance_transform_edt
from strokes import STROKES
m=np.array(Image.open('/app/target.png').convert('L'))<128
d=distance_transform_edt(m)
for name,w,pts in STROKES:
 vals=[]
 for a,b in zip(pts[:-1],pts[1:]):
  n=max(2,int(np.linalg.norm(np.subtract(b,a))))
  for t in np.linspace(0,1,n,endpoint=False):
   x=int(round(a[0]*(1-t)+b[0]*t));y=int(round(a[1]*(1-t)+b[1]*t))
   if 0<=x<1024 and 0<=y<1024 and m[y,x]:vals.append(d[y,x]*2*.22186)
 if vals:
